const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const namibia = ee.Geometry.Rectangle([11.7, -28.9, 25.3, -16.9]);

  // Time periods
  const currentStart = '2019-02-21';
  const currentEnd = '2019-02-28';
  const baselineStart = '2003-02-21';
  const baselineEnd = '2017-02-28';

  // 2. Data Acquisition
  const modisCol = ee.ImageCollection('MODIS/006/MOD13Q1')
    .select('NDVI');

  // Current period (2019)
  const currentCol = modisCol
    .filterDate(currentStart, currentEnd)
    .filterBounds(namibia);

  // Baseline period (2003-2017, Feb 21-28 each year)
  const baselineCol = modisCol
    .filterDate(baselineStart, baselineEnd)
    .filter(ee.Filter.calendarRange(51, 58, 'day_of_year')) // Feb 21-28
    .filterBounds(namibia);

  // Check collection sizes
  const currentSize = currentCol.size().getInfo();
  const baselineSize = baselineCol.size().getInfo();

  console.log(`2019 Images: ${currentSize}, Baseline Images: ${baselineSize}`);

  if (currentSize === 0 || baselineSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI
  const currentNdvi = currentCol.mean();
  const baselineNdvi = baselineCol.mean();

  // Get pixel counts to check for valid data
  const currentCount = currentNdvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const baselineCount = baselineNdvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid pixels - Current: ${currentCount}, Baseline: ${baselineCount}`);

  if (currentCount === 0 || baselineCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean NDVI values
  const currentMean = currentNdvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const baselineMean = baselineNdvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`NDVI - Current: ${currentMean?.toFixed(4)}, Baseline: ${baselineMean?.toFixed(4)}`);

  // 4. Validation & Final Answer
  if (currentMean === null || baselineMean === null || 
      isNaN(currentMean) || isNaN(baselineMean) ||
      currentMean < -1 || currentMean > 1 || baselineMean < -1 || baselineMean > 1) {
    console.log("<answer>C3</answer>");
  } else if (currentMean < baselineMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
